\title{The Combinatorics and Probability of the Library of Babel}
\author{Aristotle}
\date{June 19, 2026}

\begin{document}
\begin{abstract}
We give an exact combinatorial and probabilistic analysis of Borges' \emph{Library
of Babel}, modeled as the finite set of all strings of length $L$ over an alphabet
of $b$ symbols under the uniform counting measure. We prove the library's
cardinality $b^L$, the singleton probability $b^{-L}$, the exact expected number of
occurrences $(L-k+1)b^{-k}$ of a fixed length-$k$ pattern, and a union upper bound on
the containment probability; then a coincidence probability for two independent
volumes, the elementary ceiling $\prob\le 1$, an exact count of volumes avoiding a
pattern on every aligned block, and a resulting two-sided estimate. The lower bound,
realized by an explicit reindexing bijection between a volume and its block
decomposition, is non-vacuous for every $L$ and yields a \emph{Borges completeness}
theorem: for $b\ge 2$, the probability that a uniformly random volume contains a fixed
pattern tends to $1$ as $L\to\infty$. All results have been formally verified.
\end{abstract}

\maketitle

\section{Introduction}
Borges' 1941 story \emph{La biblioteca de Babel} describes a library containing every
book of a fixed format ($410$ pages of $40$ lines of $80$ characters in a $25$-symbol
alphabet), hence $25^{1312000}$ volumes---a number with roughly $1.8$ million digits,
dwarfing the $\approx 10^{80}$ atoms of the observable universe, yet finite. We make
the underlying questions precise and answer them.

\subsection{The model}
Fix $b$ (alphabet size) and $L$ (book length).
\begin{definition}[Volume]
A \emph{volume} is a function $v:\Fin L\to\Fin b$. We write $\Vol\,b\,L$ for the type
of volumes.
\end{definition}
\begin{definition}[Library]
The \emph{library} $\Lib\,b\,L$ is the finite set of all volumes.
\end{definition}
\begin{definition}[Counting probability]
For a finite type $\alpha$, sample set $s\subseteq\alpha$, and event $A\subseteq\alpha$,
$\prob(s,A)=\#(s\cap A)/\#s$. With $s=\Lib\,b\,L$ this is the uniform measure.
\end{definition}
\begin{definition}[Reading and occurrence]
$\mathrm{readAt}(v,n)=\mathrm{some}\,v(n)$ if $n<L$ and $\mathrm{none}$ otherwise. A
\emph{pattern} of length $k$ is $p:\Fin k\to\Fin b$. It \emph{occurs at} $i$, written
$\mathrm{OccursAt}(p,v,i)$, if $\mathrm{readAt}(v,i+j)=\mathrm{some}\,p(j)$ for all
$j\in\Fin k$. The \emph{occurrence count} is
$\mathrm{occ}(p,v)=\#\{i\in\{0,\dots,L-k\}:\mathrm{OccursAt}(p,v,i)\}$, and $v$
\emph{contains} $p$ if $\mathrm{OccursAt}(p,v,i)$ for some $i$.
\end{definition}
\begin{definition}[Expected occurrences]
$\mathbb{E}[\mathrm{occ}(p)]=\big(\sum_{v}\mathrm{occ}(p,v)\big)/\#(\Lib\,b\,L)$.
\end{definition}

\section{Foundational results}

\begin{theorem}[\texttt{card\_library}]
$\#(\Lib\,b\,L)=b^{L}$.
\end{theorem}
\begin{proof}[Proof sketch]
The library is the full function type $\Fin L\to\Fin b$; there are $b^L$ such
functions.
\end{proof}

\begin{theorem}[\texttt{prob\_singleton}]
For every volume $v$, $\prob(\Lib\,b\,L,\{v\})=b^{-L}$.
\end{theorem}
\begin{proof}[Proof sketch]
The filter to $\{v\}$ has cardinality $1$, so $\prob=1/b^{L}=b^{-L}$ by Theorem~1.
\end{proof}

\begin{lemma}[\texttt{card\_filter\_agree}]
For finite types $\alpha,\beta$, a decidable predicate $p$ on $\alpha$, and fixed
$g:\alpha\to\beta$, the number of $v:\alpha\to\beta$ with $v(a)=g(a)$ whenever $p(a)$
equals $(\#\beta)^{\#\{a:\neg p(a)\}}$.
\end{lemma}
\begin{proof}[Proof sketch]
Identify the constrained functions with $\prod_a (\text{if }p(a)\text{ then }\{g(a)\}
\text{ else }\mathrm{univ})$; the cardinality is the product of factor sizes.
\end{proof}

\begin{lemma}[\texttt{card\_agree\_inj}]
For an injection $\varphi:\Fin k\to\Fin L$ and pattern $p$, the number of volumes
with $v(\varphi(j))=p(j)$ for all $j$ is $b^{\,L-k}$.
\end{lemma}
\begin{proof}[Proof sketch]
Apply Lemma~1 with predicate ``position lies in $\mathrm{im}\,\varphi$''; injectivity
gives exactly $k$ constrained and $L-k$ free positions (with $b=0$ handled
separately).
\end{proof}

\begin{lemma}[\texttt{card\_occursAt}]
If $i+k\le L$ then $\#\{v:\mathrm{OccursAt}(p,v,i)\}=b^{\,L-k}$.
\end{lemma}
\begin{proof}[Proof sketch]
The map $j\mapsto i+j$ is an injection $\Fin k\to\Fin L$, and $\mathrm{OccursAt}(p,v,i)$
is agreement along it; apply Lemma~2.
\end{proof}

\begin{theorem}[\texttt{expected\_substring\_count}]
If $k\le L$ and $b>0$, then $\mathbb{E}[\mathrm{occ}(p)]=(L-k+1)\,b^{-k}$.
\end{theorem}
\begin{proof}[Proof sketch]
Exchange summation:
$\sum_v\mathrm{occ}(p,v)=\sum_{i=0}^{L-k}\#\{v:\mathrm{OccursAt}(p,v,i)\}
=(L-k+1)\,b^{\,L-k}$ by Lemma~3. Divide by $b^{L}$ (Theorem~1) and simplify
$b^{L-k}/b^{L}=b^{-k}$; $b>0$ makes the denominator nonzero.
\end{proof}

\begin{theorem}[\texttt{prob\_contains\_substring\_bound}]
If $k\le L$, then $\prob(\Lib\,b\,L,\{v:\mathrm{Contains}(p,v)\})\le(L-k+1)\,b^{-k}$.
\end{theorem}
\begin{proof}[Proof sketch]
Containment is the union over $i\in\{0,\dots,L-k\}$ of $\mathrm{OccursAt}(p,\cdot,i)$;
by subadditivity the count is $\le\sum_i b^{\,L-k}=(L-k+1)b^{\,L-k}$ (Lemma~3). Divide
by $b^{L}$. Cases $b=0$, $k=0$ are dispatched directly.
\end{proof}

\section{Coincidence and the trivial ceiling}

\begin{theorem}[\texttt{prob\_pair\_coincide}]
$\prob(\Lib\,b\,L\times\Lib\,b\,L,\{(u,w):u=w\})=b^{-L}$.
\end{theorem}
\begin{proof}[Proof sketch]
The product has $b^{2L}$ points; the diagonal is the image of $v\mapsto(v,v)$, hence
$b^{L}$ points; $\prob=b^{L}/b^{2L}=b^{-L}$.
\end{proof}

\begin{proposition}[\texttt{prob\_le\_one}]
For any finite type $\alpha$, set $s$, event $A$: $\prob(s,A)\le 1$.
\end{proposition}
\begin{proof}[Proof sketch]
$\#(s\cap A)\le\#s$.
\end{proof}

\section{The disjoint-block count and the two-sided estimate}

Set $m=\lfloor L/k\rfloor$. Partition $\{0,\dots,L-1\}$ into $m$ aligned blocks of
length $k$ (block $t$ on positions $\{tk,\dots,tk+k-1\}$) plus a remainder of
$L-mk$ free positions.

\begin{definition}[\texttt{NoAlignedBlockMatch}]
$v$ \emph{has no aligned block match} if $\neg\,\mathrm{OccursAt}(p,v,tk)$ for all
$t\in\Fin m$.
\end{definition}

\begin{definition}[\texttt{blockEquiv}]
Given $h:mk+(L-mk)=L$, there is a bijection
\[
\mathrm{blockEquiv}:\Vol\,b\,L\ \simeq\ \big((\Fin m\to\Fin k\to\Fin b)\times(\Fin(L-mk)\to\Fin b)\big),
\]
assembled from the standard product/sum/curry equivalences. Under it, block $t$ at
offset $j$ reads the original position $tk+j$ (\texttt{blockEquiv\_fst\_apply},
\texttt{blockEquiv\_index}).
\end{definition}

\begin{lemma}[\texttt{noAligned\_iff}]
If $k>0$, then $\mathrm{NoAlignedBlockMatch}(p,v)$ holds iff every block of
$\mathrm{blockEquiv}(v)$ differs from $p$.
\end{lemma}
\begin{proof}[Proof sketch]
By \texttt{blockEquiv\_index}, $\mathrm{OccursAt}(p,v,tk)$ states exactly that block
$t$ equals $p$; negate and quantify over $t$.
\end{proof}

\begin{lemma}[\texttt{card\_avoid}]
$\#\{g:\Fin m\to(\Fin k\to\Fin b)\mid\forall t,\,g(t)\ne p\}=(b^{k}-1)^{m}$.
\end{lemma}
\begin{proof}[Proof sketch]
The set is $\prod_t(\mathrm{univ}\setminus\{p\})$ with $m$ factors of size $b^k-1$.
\end{proof}

\begin{theorem}[\texttt{card\_noAlignedBlockMatch}]
If $k>0$,
\[
\#\{v:\mathrm{NoAlignedBlockMatch}(p,v)\}=(b^{k}-1)^{\lfloor L/k\rfloor}\,
b^{\,L-\lfloor L/k\rfloor\,k}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Transport across $\mathrm{blockEquiv}$ (Lemma~4): the block component is a
pattern-free $m$-tuple (Lemma~5, $(b^k-1)^m$) and the remainder is arbitrary
($b^{L-mk}$); a bijection multiplies the counts.
\end{proof}

\begin{theorem}[\texttt{prob\_contains\_substring\_lower\_bound}]
\[
\prob(\Lib\,b\,L,\{v:\mathrm{Contains}(p,v)\})\ \ge\ 1-\big(1-b^{-k}\big)^{\lfloor L/k\rfloor}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Non-containment $\subseteq$ NoAlignedBlockMatch. By Theorem~6 and Theorem~1, the
no-match probability is $(b^k-1)^m b^{L-mk}/b^L=(1-b^{-k})^m$ with $m=\lfloor L/k\rfloor$.
Complement. The inclusion is one-directional and exact---no inclusion--exclusion.
\end{proof}

Combining Theorems~5 and~7 sandwiches the containment probability:
\[
1-\big(1-b^{-k}\big)^{\lfloor L/k\rfloor}\ \le\ \prob(\mathrm{Contains})\ \le\ (L-k+1)\,b^{-k}.
\]

\section{Borges completeness}

\begin{theorem}[\texttt{prob\_contains\_tendsto\_one}]
For $b\ge 2$ and fixed $p$ of length $k\ge 1$,
\[
\lim_{L\to\infty}\prob(\Lib\,b\,L,\{v:\mathrm{Contains}(p,v)\})=1.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Here $0\le 1-b^{-k}<1$ and $\lfloor L/k\rfloor\to\infty$, so
$(1-b^{-k})^{\lfloor L/k\rfloor}\to 0$ and the lower bound of Theorem~7 tends to $1$;
with $\prob\le 1$ (Proposition~1), squeeze.
\end{proof}

Any fixed text almost surely appears inside a sufficiently long random volume:
length alone, not design, forces the appearance.

\section{The catalog question}
Addressing one of $b^L$ volumes needs $\log_2(b^L)=L\log_2 b$ bits; a single volume
carries $L\log_2 b$ bits, enough to name only one other volume. Since $b^L\gg
L\log_2 b$, no single volume can catalog all others. A distributed catalog over $N$
volumes carries $N L\log_2 b$ bits and suffices once $N>b^L/(L\log_2 b)$. (This uses
only $\#(\Lib\,b\,L)=b^L$ from Theorem~1 and an information-theoretic count.)

\section{Applications}
The model is the canonical fixed-size information space: Theorem~3 is the expected
motif count in random DNA ($b=4$); Theorem~2 is key-guessing probability; the
disjoint-block method (Theorems~6--8) is the standard route to ``a random word almost
surely contains any fixed factor''; \S7 is the source-coding bound that no
fixed-length codeword indexes a larger message set.

\section{Future directions}
\begin{conjecture}[Sharp asymptotics]
In the regime $L b^{-k}\to\lambda$, $\prob_L(\mathrm{contains})=1-e^{-(L-k+1)b^{-k}}
+o(1)$, via a Chen--Stein total-variation bound to $\mathrm{Poisson}(\lambda)$ on the
dependency graph of overlapping windows.
\end{conjecture}
\begin{conjecture}[Variance / second moment]
$\Var(\mathrm{occ})=(L-k+1)b^{-k}(1-b^{-k})+2\sum_{1\le d<k}(\text{overlap term})$,
governed by the border/period structure of $p$; Paley--Zygmund then gives an all-$L$
lower bound.
\end{conjecture}
\begin{conjecture}[Autocorrelation]
Overlap-free (bifix-free) patterns minimize $\Var(\mathrm{occ})$ and maximize
$\prob(\mathrm{contains})$ for every $L$.
\end{conjecture}
\begin{conjecture}[Coupon collector]
For $T$ = draws until all $b^L$ volumes appear, $\mathbb{E}[T]=b^L H_{b^L}$ and
$T/(b^L\log b^L)\to 1$ in probability.
\end{conjecture}
\begin{conjecture}[Distinct $k$-grams]
$\mathbb{E}[D_L]=b^k(1-(1-b^{-k})^{L-k+1})+\text{correction}$ and $D_L/b^k\to 1$ once
$L\gg k b^k$.
\end{conjecture}

\section{Conclusion}
The Library of Babel admits a complete exact elementary theory: $b^L$ volumes each of
probability $b^{-L}$; a fixed pattern occurs $(L-k+1)b^{-k}$ times on average; and the
containment probability is sandwiched between $1-(1-b^{-k})^{\lfloor L/k\rfloor}$ and
$(L-k+1)b^{-k}$, the lower bound (via an explicit block-reindexing bijection) forcing
asymptotic certainty---the mathematical realization of Borges' dream.

\end{document}

