"""Demo: Borges completeness (Theorem `prob_contains_tendsto_one`).
For b >= 2 the disjoint-block lower bound 1 - (1 - b^-k)^(L//k) tends to 1
as L grows, so a long enough random volume almost surely contains any fixed
pattern.  Here b=25 (Borges' alphabet), k=3 (e.g. 'the')."""
from __future__ import annotations
from fractions import Fraction

def lower_bound(b: int, L: int, k: int) -> Fraction:
    m = L // k
    return Fraction(1) - Fraction(b ** k - 1, b ** k) ** m

def expected(b: int, L: int, k: int) -> Fraction:
    return Fraction(L - k + 1, b ** k)

if __name__ == "__main__":
    b, k = 25, 3
    for L in (3, 100, 10_000, 1_000_000, 1_312_000):
        print(f"L={L:>9,}: lower={float(lower_bound(b, L, k)):.10f} "
              f"E[occ]={float(expected(b, L, k)):.4f}")

