function DE_BRUIJN(b, n):
    a <- array of zeros, length b*n
    seq <- empty list
    function DB(t, p):
        if t > n:
            if n mod p == 0: append a[1..p] to seq
        else:
            a[t] <- a[t-p]; DB(t+1, p)
            for j from a[t-p]+1 to b-1: a[t] <- j; DB(t+1, t)
    DB(1, 1)
    return concatenation of seq
